import test from 'node:test';
import assert from 'node:assert/strict';
import {groupLabels} from '../src/group-labels.js';
test('consumer behaviour',()=>assert.deepEqual(groupLabels([' z ','A','A',' ',' b']),['A','b','z']));
test('English order',()=>assert.deepEqual(groupLabels(['a','B']),['a','B']));
test('input preserved',()=>{const xs=[' x ','x'];groupLabels(xs);assert.deepEqual(xs,[' x ','x']);});
